r multiplexed and portable cancer diagnostics |journal=Nature Nanotechnology |date=24 April 2023 |volume=18 |issue=7 |pages=798–807 |doi=10.1038/s41565-023-01372-9 |pmid=37095220 |pmc=10359190 |bibcode=2023NatNa..18..798H |language=en |issn=1748-3395|doi-access=free}}</ref>
