14=Li |first14=Guochuan |last15=Wu |first15=Ling |last16=Jiang |first16=Yiwen |last17=Qian |first17=Weiran |last18=Zhang |first18=Li |last19=Peng |first19=Wanling |last20=Xu |first20=Min |last21=Hu |first21=Ji |last22=Jiang |first22=Man |last23=Chen |first23=Liangyi |last24=Tang |first24=Chao |last25=Zhu |first25=Yingjie |last26=Lin |first26=Dayu |last27=Zhou |first27=Jiang-Ning |last28=Li |first28=Yulong |title=A tool kit of highly selective and sensitive genetically encoded neuropeptide sensors |journal=Science |date=17 November 2023 |volume=382 |issue=6672 |article-number=eabq8173 |doi=10.1126/science.abq8173 |pmid=37972184 |pmc=11205257 |bibcode=2023Sci...382q8173W |language=en |issn=0036-8075|biorxiv=10.1101/2022.03.26.485911|s2cid=265221583 }}</ref>
